const plans={
  basic20:{name:'Basic - ChatGPT',price:'$20',copy:'A focused monthly plan for visibility on ChatGPT.',back:'/products/basic-monthly-plan',features:['ChatGPT visibility coverage','Monthly listing health checks','Business information monitoring','Weekly Tips & Tricks to Boost your Business']},
  basic40:{name:'Basic - Multi-platform',price:'$40',copy:'Broader monthly visibility across three leading AI platforms.',back:'/products/basic-monthly-plan',features:['ChatGPT, Gemini and Copilot coverage','Monthly listing health checks','Business information monitoring','Weekly Tips & Tricks to Boost your Business']},
  growth100:{name:'Growth Plan',price:'$100',copy:'Advanced AI visibility tuning for businesses ready to grow.',back:'/products/growth-monthly-plan',features:['Everything in Basic','Advanced AI-SEO tuning','Priority email support','Weekly Tips & Tricks to Boost your Business']},
  business250:{name:'Business Plan',price:'$250',copy:'Expanded AI visibility support across major platforms.',back:'/products/business-monthly-plan',features:['Multi-platform AI coverage','Ongoing listing management','Priority business support','Weekly Tips & Tricks to Boost your Business']}
};
const query=new URLSearchParams(location.search);const planKey=query.get('plan');const BILLING=query.get('billing')==='year'?'year':'monthly';
if(window.fbq&&!sessionStorage.getItem('fbq-ic-'+planKey)){sessionStorage.setItem('fbq-ic-'+planKey,'1');window.fbq('track','InitiateCheckout');}const plan=plans[planKey];const loading=document.querySelector('#checkout-loading');const errorBox=document.querySelector('#checkout-error');let checkout;
if(!plan){location.replace('/#pricing')}else{document.title=`${plan.name} Checkout | UNIRAB`;document.querySelector('#plan-name').textContent=plan.name;document.querySelector('#plan-price').textContent=plan.price;document.querySelector('#plan-copy').textContent=plan.copy;document.querySelector('#back-link').href=plan.back;document.querySelector('#plan-features').innerHTML=plan.features.map(feature=>`<li>${feature}</li>`).join('');startCheckout()}
async function startCheckout(){loading.hidden=false;errorBox.hidden=true;document.querySelector('#embedded-checkout').replaceChildren();let form=null;try{const storageKey='unirab-'+(planKey.startsWith('basic')?'basic':planKey.startsWith('growth')?'growth':'business');const raw=sessionStorage.getItem(storageKey);if(raw){form=JSON.parse(raw);sessionStorage.setItem('unirab-last-order',raw)}}catch(e){}try{const response=await fetch('/api/create-checkout-session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({plan:planKey,billing:BILLING,form})});const result=await response.json();if(!response.ok||!result.clientSecret)throw new Error(result.error||'Secure checkout is unavailable.');const stripe=Stripe('pk_live_51S3IyW0ArfCxocSQuVAFxaO3RClnupysEfm1oWg8v4uXUE95MGdvVqrTFoFWXzK8ddZODm2AfXgpKISe9wBk7Sob00MFqzJrKm');checkout=await stripe.initEmbeddedCheckout({clientSecret:result.clientSecret});loading.hidden=true;checkout.mount('#embedded-checkout')}catch(error){loading.hidden=true;errorBox.hidden=false;errorBox.querySelector('p').textContent=error.message||'Please try again.'}}
document.querySelector('#retry').addEventListener('click',()=>{checkout?.destroy();startCheckout()});
